const fs = require('fs');
const core = fs.readFileSync('lib/doc-container.js', 'utf8');
const wrapped =
  '// <doc-container-core> (generated by scripts/inline-doc-container.js — do not edit by hand)\n' +
  'const docContainer = (function(){ const module = { exports: {} };\n' +
  core + '\n' +
  'return module.exports; })();\n' +
  '// </doc-container-core>';
const main = fs.readFileSync('main.js', 'utf8')
  .replace(/\/\/ <doc-container-core>[\s\S]*?\/\/ <\/doc-container-core>/, wrapped);
fs.writeFileSync('main.js', main);
console.log('inlined lib/doc-container.js into main.js');
